#include "word_core.hpp"
int main(int argc,char**argv){if(argc<3)return 2;auto start=chrono::steady_clock::now();PolyWord p;auto tar=read_target(argv[1],6,-1);QP out;int i=0;for(auto[w,c]:tar){for(auto[m,d]:p.get(w))qadd(out,m,c*d);if(++i%10000==0){cerr<<"CONVERT "<<i<<" terms="<<out.size()<<" cache="<<p.cache.size()<<" seconds="<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<"\n";if(p.cache.size()>250000)p.cache.clear();}}save_poly(argv[2],out);map<pair<int,int>,int>counts;for(auto[m,c]:out){auto a=monvec(m);int n=0,M=0;for(W w:a){if(wn(w)>n){n=wn(w);M=maxw(w);}else if(wn(w)==n)M=max(M,maxw(w));}counts[{n,M}]++;}for(auto[k,c]:counts)cerr<<"MAX_FACTOR "<<k.first<<" "<<k.second<<" count="<<c<<"\n";cerr<<"COMPLETE "<<out.size()<<"\n";}
